#!/usr/bin/env node
/**
 * Token pipeline: tokens.json (DTCG) → tokens.css (Tailwind v4 @theme) + tokens.ts (typed JS).
 *
 *   node scripts/build-tokens.mjs          write generated files
 *   node scripts/build-tokens.mjs --check  fail (exit 1) if generated files are out of date
 *
 * The --check mode runs before every production build, so code can never ship with
 * tokens that drifted from the source of truth.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const dir = resolve(root, 'src/design-system/tokens');
const source = JSON.parse(readFileSync(resolve(dir, 'tokens.json'), 'utf8'));
const check = process.argv.includes('--check');

const HEADER = '/* AUTO-GENERATED by scripts/build-tokens.mjs from tokens.json. Do not edit by hand. */';

/** Walk a DTCG group and yield [path[], token] for each leaf that has $value. */
function* walk(node, path = [], inheritedType) {
  const type = node.$type ?? inheritedType;
  if ('$value' in node) {
    yield [path, { ...node, $type: type }];
    return;
  }
  for (const [key, child] of Object.entries(node)) {
    if (key.startsWith('$')) continue;
    yield* walk(child, [...path, key], type);
  }
}

const cssLines = [];
const flat = {};

const toCubic = (v) => `cubic-bezier(${v.join(', ')})`;

for (const [path, token] of walk(source)) {
  const [group, ...rest] = path;
  const name = rest.join('-');
  const v = token.$value;
  flat[path.join('.')] = token.$type === 'cubicBezier' ? toCubic(v) : v;

  switch (group) {
    case 'color':
      cssLines.push(`  --color-${name}: ${v};`);
      break;
    case 'font':
      cssLines.push(`  --font-${name}: ${v};`);
      break;
    case 'text':
      cssLines.push(`  --text-${name}: ${v.fontSize};`);
      cssLines.push(`  --text-${name}--line-height: ${v.lineHeight};`);
      break;
    case 'spacing':
      if (name === 'unit') cssLines.push(`  --spacing: ${v};`);
      break;
    case 'radius':
      cssLines.push(`  --radius-${name}: ${v};`);
      break;
    case 'shadow':
      cssLines.push(`  --shadow-${name}: ${v};`);
      break;
    case 'duration':
      cssLines.push(`  --duration-${name}: ${v};`);
      break;
    case 'ease':
      cssLines.push(`  --ease-${name}: ${toCubic(v)};`);
      break;
    case 'breakpoint':
      cssLines.push(`  --breakpoint-${name}: ${v};`);
      break;
    default:
      throw new Error(`Unknown token group "${group}" at ${path.join('.')}`);
  }
}

const css = `${HEADER}
/*
 * Tailwind's default palette, radii, shadows and type scale are reset with "initial",
 * so only Groundwork tokens exist as utilities (e.g. bg-paper-raised, text-ink-secondary).
 * Using an unknown color like "bg-blue-500" produces no CSS.
 */
@theme {
  --color-*: initial;
  --font-*: initial;
  --text-*: initial;
  --radius-*: initial;
  --shadow-*: initial;
  --breakpoint-*: initial;
  --color-transparent: transparent;
  --color-current: currentColor;
  --color-white: #ffffff;
${cssLines.join('\n')}
}
`;

const ts = `${HEADER}
export const tokens = ${JSON.stringify(flat, null, 2)} as const;

export type TokenName = keyof typeof tokens;
`;

const outputs = [
  [resolve(dir, 'tokens.css'), css],
  [resolve(dir, 'tokens.ts'), ts],
];

let stale = false;
for (const [file, content] of outputs) {
  const current = existsSync(file) ? readFileSync(file, 'utf8').replace(/\r\n/g, '\n') : '';
  if (current === content) continue;
  if (check) {
    console.error(`✗ ${file} is out of date. Run "npm run tokens".`);
    stale = true;
  } else {
    writeFileSync(file, content);
    console.log(`✓ wrote ${file}`);
  }
}
if (stale) process.exit(1);
if (check) console.log(`✓ tokens up to date (${Object.keys(flat).length} tokens)`);
